<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GPX Repair Studio - Mobile View</title>
    <style>
        :root {
            --primary: #ea580c; /* Orange-600 */
            --primary-hover: #c2410c;
            --bg-color: #f8f9fa;
            --text-main: #111827;
            --text-muted: #6b7280;
            --border-color: #e5e7eb;
            --white: #ffffff;
            --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            -webkit-font-smoothing: antialiased;
        }

        body {
            font-family: var(--font-family);
            background-color: var(--bg-color);
            color: var(--text-main);
            height: 100vh;
            width: 100vw;
            max-width: 390px; /* Constraint for mobile simulation */
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            overflow-x: hidden; /* Prevent horizontal scroll */
            position: relative;
        }

        /* --- Header --- */
        header {
            background: var(--white);
            padding: 12px 16px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 1px solid var(--border-color);
            flex-shrink: 0;
            z-index: 10;
        }

        .app-title {
            font-size: 18px;
            font-weight: 700;
            letter-spacing: -0.02em;
        }

        .header-actions {
            display: flex;
            gap: 8px;
        }

        .btn-header {
            display: flex;
            align-items: center;
            gap: 6px;
            border: 1px solid var(--border-color);
            background: var(--white);
            padding: 6px 12px;
            border-radius: 6px;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            white-space: nowrap;
        }

        .btn-header svg {
            width: 14px;
            height: 14px;
        }

        /* --- Map Area --- */
        .map-container {
            flex-grow: 1;
            position: relative;
            background-color: #f3f4f6;
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* Simulated Map Background */
        .map-bg {
            width: 100%;
            height: 100%;
            background-image: 
                linear-gradient(#e5e7eb 1px, transparent 1px),
                linear-gradient(90deg, #e5e7eb 1px, transparent 1px);
            background-size: 40px 40px;
            position: absolute;
            top: 0;
            left: 0;
            opacity: 0.6;
            z-index: 0;
        }

        /* Map Overlay Elements */
        .map-overlay-card {
            position: absolute;
            top: 16px;
            left: 16px;
            background: rgba(255,255,255, 0.95);
            backdrop-filter: blur(4px);
            padding: 12px 16px;
            border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
            z-index: 2;
            max-width: 220px;
            border: 1px solid rgba(0,0,0,0.05);
        }

        .status-badge {
            display: inline-flex;
            align-items: center;
            gap: 4px;
            font-size: 11px;
            font-weight: 600;
            color: #dc2626; /* Reddish */
            margin-bottom: 4px;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .distance-val {
            font-size: 28px;
            font-weight: 800;
            line-height: 1;
            color: #111;
        }

        .distance-unit {
            font-size: 16px;
            font-weight: 600;
        }

        .est-badge {
            display: inline-flex;
            align-items: center;
            background: #fee2e2;
            color: #991b1b;
            font-size: 11px;
            font-weight: 600;
            padding: 2px 6px;
            border-radius: 4px;
            margin-left: 8px;
            vertical-align: middle;
        }

        .map-stats {
            font-size: 12px;
            color: var(--text-muted);
            margin-top: 6px;
            line-height: 1.3;
        }

        /* Map Controls (Right Side) */
        .map-controls-right {
            position: absolute;
            right: 12px;
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 2;
        }

        .control-btn {
            width: 40px;
            height: 40px;
            background: var(--white);
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            border: none;
            cursor: pointer;
            color: #374151;
        }

        .control-btn.active {
            background: var(--primary);
            color: white;
        }

        .control-btn svg {
            width: 20px;
            height: 20px;
        }

        /* Simulated Drawing (The Loop) */
        .drawing-layer {
            position: absolute;
            z-index: 1;
            width: 100%;
            height: 100%;
            pointer-events: none;
        }

        .loop-svg {
            width: 120px;
            height: 120px;
            position: absolute;
            top: 45%; /* Adjusted to match screenshot roughly */
            left: 20%;
            transform: translate(-50%, -50%);
            overflow: visible;
        }

        .loop-path {
            fill: none;
            stroke: var(--primary);
            stroke-width: 3;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .point-node {
            fill: var(--white);
            stroke: var(--primary);
            stroke-width: 2;
            r: 5;
        }

        .point-node.selected {
            fill: var(--primary);
            r: 6;
        }

        /* --- Bottom Sheet / Tools Panel --- */
        .tools-panel {
            background: var(--white);
            border-top: 1px solid var(--border-color);
            border-radius: 16px 16px 0 0;
            padding: 16px;
            box-shadow: 0 -4px 20px rgba(0,0,0,0.05);
            flex-shrink: 0;
            max-height: 55vh;
            overflow-y: auto;
            z-index: 20;
        }

        .panel-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            cursor: pointer;
        }

        .panel-title {
            font-weight: 600;
            font-size: 15px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .panel-title::before {
            content: '';
            display: block;
            width: 16px;
            height: 3px;
            background: #d1d5db;
            border-radius: 2px;
        }

        .chevron-down {
            width: 20px;
            height: 20px;
            color: #9ca3af;
        }

        /* Action Buttons */
        .action-stack {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 12px;
        }

        .btn-action {
            background: var(--primary);
            color: white;
            border: none;
            padding: 10px 16px;
            border-radius: 6px;
            font-weight: 600;
            font-size: 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            cursor: pointer;
            width: 100%;
            transition: background 0.2s;
        }

        .btn-action:hover {
            background: var(--primary-hover);
        }

        .btn-action svg {
            width: 16px;
            height: 16px;
        }

        .helper-text {
            font-size: 13px;
            color: var(--text-muted);
            margin-bottom: 16px;
            line-height: 1.4;
        }

        .info-text {
            font-size: 13px;
            color: #4b5563;
            margin-bottom: 16px;
            line-height: 1.5;
        }

        /* Selection Bar */
        .selection-bar {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            font-size: 13px;
            color: #374151;
        }

        .selection-actions {
            display: flex;
            gap: 8px;
        }

        .btn-small {
            background: transparent;
            border: 1px solid var(--border-color);
            padding: 4px 10px;
            border-radius: 4px;
            font-size: 12px;
            cursor: pointer;
            color: #374151;
        }

        /* Points List */
        .points-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .point-item {
            display: flex;
            align-items: center;
            background: #fff7ed; /* Very light orange bg */
            border: 1px solid #ffedd5;
            padding: 8px 12px;
            border-radius: 6px;
            font-size: 13px;
            font-family: monospace;
            color: #431407;
        }

        .checkbox-mock {
            width: 16px;
            height: 16px;
            background: var(--primary);
            border-radius: 3px;
            margin-right: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 11px;
        }

        .coord-text {
            flex-grow: 1;
        }

        .delete-icon {
            color: #9ca3af;
            cursor: pointer;
            font-size: 16px;
            font-weight: bold;
        }

        /* Compass */
        .compass {
            position: absolute;
            bottom: 240px; /* Above panel approx */
            left: 12px;
            width: 36px;
            height: 36px;
            background: #374151;
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 14px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.2);
            z-index: 5;
        }

    </style>
</head>
<body>

    <!-- Header -->
    <header>
